-- Группа 3: кнопки и отделы, перенесённые напрямую в основной <leader> (поиск, Git <leader>V, Go, БД/DAP, плагины <leader>L, HUD <leader>l, тесты, Obsidian, Trouble).
return {
  { lhs = "<leader>fw", name = "Найти слово под курсором", doc = "Telescope: поиск слова под курсором по всему проекту (grep_string)." },
  { lhs = "<leader>fm", name = "Метки (marks)", doc = "Telescope: список закладок (marks) текущего файла и проекта." },
  { lhs = "<leader>fF", name = "Дерево: найти / создать файл", doc = "Открывает дерево файлов на текущем файле (:NvimTreeFindFileToggle); клавиша a внутри дерева создаёт новый файл." },
  { lhs = "<leader>rf", name = "Переименовать файл", doc = "Переименовывает текущий файл через snacks.rename.rename_file()." },
  { lhs = "<leader>V", name = "Отдел Git · Diffview · Конфликты", doc = "Группа Git-операций: stage/undo hunk, blame, diff, LazyGit, Diffview и разрешение мерж-конфликтов." },
  { lhs = "<leader>Vs", name = "Stage hunk", doc = "Git: добавляет в индекс (stage) изменённый фрагмент под курсором (gitsigns)." },
  { lhs = "<leader>Vu", name = "Undo stage hunk", doc = "Git: отменяет stage для фрагмента под курсором (gitsigns.reset_hunk)." },
