  { lhs = "<leader>Vh", name = "Предпросмотр изменений", doc = "Git: показывает diff изменённого фрагмента в плавающем окне (gitsigns.preview_hunk)." },
  { lhs = "<leader>Vd", name = "Diff текущего файла", doc = "Git: сравнение текущего файла с версией из индекса (gitsigns.diffthis)." },
  { lhs = "<leader>Vl", name = "Blame строки вкл/выкл", doc = "Git: показывает автора строки в конце строки; повторное нажатие выключает." },
