  { lhs = "<leader>gu", name = "JSON → struct", doc = "Go: из вставленного JSON генерирует структуру Go (:GoJson2Struct)." },
  { lhs = "<leader>gI", name = "Сгенерировать impl", doc = "Go: создаёт заготовку методов для реализации интерфейса (:GoImpl)." },
