  { lhs = "<leader>L", name = "Отдел Плагины и LSP", doc = "Группа управления плагинами и серверами: Lazy, Lazy sync, Mason, LspInfo, ConformInfo, checkhealth." },
  { lhs = "<leader>Ll", name = "Открыть Lazy UI", doc = "Окно менеджера плагинов Lazy (:Lazy)." },
