  { lhs = "<leader>Li", name = "Статус LSP (:LspInfo)", doc = "Показывает подключённые к буферу LSP-серверы и их статус." },
  { lhs = "<leader>Lc", name = "Чем форматируется файл", doc = "Показывает активный форматтер conform для текущего буфера (:ConformInfo)." },
  { lhs = "<leader>Lh", name = "Проверка здоровья (:checkhealth)", doc = "Запускает диагностику здоровья Neovim и плагинов (:checkhealth)." },
  { lhs = "<leader>xs", name = "Символы файла (Trouble)", doc = "Символы файла (функции, типы) в панели Trouble (:Trouble symbols toggle)." },
  { lhs = "<leader>xt", name = "TODO-комментарии (Trouble)", doc = "Список TODO/FIXME в панели Trouble (:Trouble todo toggle)." },
  { lhs = "<leader>kl", name = "Поиск по всем шпаргалкам", doc = "cheat.sh: список всех доступных шпаргалок (:CheatList)." },
}
